import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const n="/assets/189_c7958c85-7860-4d3f-b71f-4951ace18414.jB7jcCNS.png",s="/assets/184_blobid2.3hUr403-.png",m=JSON.parse('{"title":"How to Open the VNC Console for a Physical Server","description":"","frontmatter":{"title":"How to Open the VNC Console for a Physical Server"},"headers":[],"relativePath":"operations-knowledge-base/dedicated-server/how-to-open-the-vnc-console-for-a-physical-server.md","filePath":"operations-knowledge-base/dedicated-server/how-to-open-the-vnc-console-for-a-physical-server.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/dedicated-server/how-to-open-the-vnc-console-for-a-physical-server.md"};function c(l,e,h,p,d,u){return o(),r("div",null,[...e[0]||(e[0]=[a('<h2 id="i-overview" tabindex="-1">I. Overview <a class="header-anchor" href="#i-overview" aria-label="Permalink to &quot;I. Overview&quot;">​</a></h2><p>VNC allows you to remotely access your server through a web browser. If you do not have a remote login client installed, or if your remote connection is not working properly, you can use VNC to access the server console.</p><p>Through VNC, you can view the server’s real-time status and perform basic server management tasks using your server account, such as running commands or checking system logs.</p><h2 id="ii-access-path" tabindex="-1">II. Access Path <a class="header-anchor" href="#ii-access-path" aria-label="Permalink to &quot;II. Access Path&quot;">​</a></h2><ol><li>Log in to the platform and go to the <strong>Customer Center</strong>. Under <strong>My Orders</strong>, click <strong>Physical Servers</strong>. Alternatively, go to <strong>Product Management</strong> and click <strong>Physical Servers</strong>, then filter the server list by region and status.</li><li>In the product list, locate the target server and click to open the <strong>Product Details</strong> page.</li><li>Under the <strong>Server Information</strong> tab, find and click the <strong>VNC</strong> button. This will start the VNC connection and open the VNC interface.</li></ol><p><img src="'+n+'" alt=""></p><h2 id="iii-vnc-interface-functions" tabindex="-1">III. VNC Interface Functions <a class="header-anchor" href="#iii-vnc-interface-functions" aria-label="Permalink to &quot;III. VNC Interface Functions&quot;">​</a></h2><h3 id="a-top-action-bar" tabindex="-1">(A) Top Action Bar <a class="header-anchor" href="#a-top-action-bar" aria-label="Permalink to &quot;(A) Top Action Bar&quot;">​</a></h3><p><strong>Force Refresh VNC</strong> If the VNC display is abnormal or frozen, click this button to refresh the screen and restore normal display.</p><p><strong>Power On / Shut Down / Restart</strong> You can power on, shut down, or restart the server directly from the VNC interface, making it easier to manage the server’s power status.</p><hr><h3 id="b-shortcut-functions" tabindex="-1">(B) Shortcut Functions <a class="header-anchor" href="#b-shortcut-functions" aria-label="Permalink to &quot;(B) Shortcut Functions&quot;">​</a></h3><p><strong>Clipboard:</strong> If you need to enter text such as commands or passwords into the server console, first copy the text to your local clipboard. Then click “<strong>Clipboard”</strong> in the VNC interface, paste the text into the pop-up input box, and click “<strong>OK”</strong>. The text will be sent directly to the server console, which improves efficiency and avoids manual typing.</p><p><strong>Paste Password:</strong> Click this button to automatically paste the server password stored in the management panel into the console input field, making it easier to log in quickly.</p><p><strong>Send CtrlAltDel:</strong> This simulates pressing the “<strong>Ctrl + Alt + Del”</strong> key combination. In Windows, it can be used to bring up the login screen.</p><p><img src="'+s+'" alt=""></p><h2 id="iv-important-notes" tabindex="-1">IV. Important Notes <a class="header-anchor" href="#iv-important-notes" aria-label="Permalink to &quot;IV. Important Notes&quot;">​</a></h2><ol><li>When managing a server through VNC, your actions have the same permissions as local operations. Please proceed carefully to avoid accidental actions that may cause service issues or data loss.</li><li>If the VNC connection fails or the screen remains black, try &quot;Resetting the BMC&quot; in the control panel, restart the server, or contact technical support.</li></ol>',18)])])}const f=t(i,[["render",c]]);export{m as __pageData,f as default};
